UPDATE public.fishing_areas AS a
SET latitude=i.latitude, longitude=i.longitude, coordinates_imported=true,
    coordinate_status='province_checked_source_candidate',
    coordinate_note='Olta Atlası page-level spatialCoverage candidate; exact mera name and province matched; general location only; not independently cross-checked against OSM/official source; not fishing access or permission.',
    location_confidence_grade='D', source_checked_at=i.source_checked_at, updated_at=now()
FROM input AS i WHERE a.id=i.id AND a.source_slug=i.source_slug AND a.name=i.name
  AND a.province_name IS NOT DISTINCT FROM i.province_name AND (a.latitude IS NULL OR a.longitude IS NULL);
